
ALTER TABLE public.project_documents
  ADD COLUMN IF NOT EXISTS files_json jsonb NOT NULL DEFAULT '[]'::jsonb;

UPDATE public.project_documents d
SET
  file_base64 = v.file_b64,
  files_json = v.files,
  updated_at = now()
FROM (VALUES
  ('cnic', 'data:image/png;base64,', '[{"label":"Front","data":"data:image/png;base64,"},{"label":"Back","data":"data:image/png;base64,"}]'::jsonb),
  ('property', 'data:image/png;base64,', '[{"label":"Page 1","data":"data:image/png;base64,"}]'::jsonb),
  ('plan', 'data:image/png;base64,', '[{"label":"Plan","data":"data:image/png;base64,"}]'::jsonb),
  ('noc', 'data:image/png;base64,', '[{"label":"NOC","data":"data:image/png;base64,"}]'::jsonb),
  ('loan', 'data:image/png;base64,', '[{"label":"Loan docs","data":"data:image/png;base64,"}]'::jsonb),
  ('engineer_report', 'data:image/png;base64,', '[{"label":"Report","data":"data:image/png;base64,"}]'::jsonb),
  ('completion_cert', 'data:image/png;base64,', '[{"label":"Certificate","data":"data:image/png;base64,"}]'::jsonb)
) AS v(doc_type, file_b64, files)
WHERE d.doc_type = v.doc_type;

